596	+import { inject, Injectable, signal } from '@angular/core';
597	+import { filter } from 'rxjs/operators';
598	+import { OnlineMatchService } from './online-match.service';
599	+
600	+/** The wins of an online room: the host's (left) first, the guest's second. */
601	+export type Tally = readonly [host: number, guest: number];
602	+
603	+export const EMPTY_TALLY: Tally = [0, 0];
604	+
605	+/** The tally after a match `winner` won - a draw (null) counts for nobody. */
606	+export function countResult(tally: Tally, winner: 0 | 1 | null): Tally {
607	+  if (winner === null) {
608	+    return tally;
609	+  }
610	+  return winner === 0 ? [tally[0] + 1, tally[1]] : [tally[0], tally[1] + 1];
611	+}
612	+
613	+/**
614	+ * Counts the wins of the matches two devices played over one connection,
615	+ * for the room both players see. A new connection starts at nought; the
616	+ * end of one keeps its count, so its last result still shows it.
617	+ */
618	+@Injectable({ providedIn: 'root' })
619	+export class RoomTally {
620	+  private readonly state = signal<Tally>(EMPTY_TALLY);
621	+
622	+  public readonly tally = this.state.asReadonly();
623	+
624	+  public constructor() {
625	+    inject(OnlineMatchService)
626	+      .events$.pipe(filter((event) => event.type === 'connected'))
627	+      .subscribe(() => this.state.set(EMPTY_TALLY));
628	+  }
629	+
630	+  /** Counts a match of the room for the seat that won it. */
631	+  public count(winner: 0 | 1 | null): void {
632	+    this.state.update((tally) => countResult(tally, winner));
633	+  }
634	+}
